export type ProductKey = keyof typeof PRODUCT_MESSAGES;
export const PRODUCT_LOCALES = ["en-US", "zh-CN", "de-DE", "fr-FR", "ja-JP", "ko-KR", "zh-TW"] as const;
export function productText(locale: string, key: ProductKey): string {
  const index = PRODUCT_LOCALES.indexOf(locale as typeof PRODUCT_LOCALES[number]);
  return PRODUCT_MESSAGES[key][index < 0 ? 0 : index];
}
export function useProduct() {
  const { locale } = useLocale();
  return (key: ProductKey) => productText(locale, key);
}
